// Ready template bundled with the app so download needs no session or static-file redirect.
const encoded =
  "";
export const readyTemplateName = "Mau-nhap-nhiem-vu-Nam-Sach.xlsx";
export const excelMime =
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
export function readyTemplateBytes() {
  return Uint8Array.from(atob(encoded), (c) => c.charCodeAt(0));
}
